Chart.defaults.color = '#8b949e'; // Color de texto
Chart.defaults.borderColor = '#30363d'; // Color de líneas de división
document.addEventListener("DOMContentLoaded", function () {
    localStorage.clear();
    $(".dropdown-trigger").dropdown();   

    actualizarKpisTransacciones(dataTransacciones);
    M.AutoInit();
    renderizarGraficoProductividad(dataTransacciones);
    renderizarTopArticulos(dataTransacciones);
    renderizarGraficoPrecision(dataTransacciones);
    renderizarTablaTotales(dataTransacciones);
});
/**
 * @function actualizarKpisTransacciones
 * @description Procesa dataTransacciones para actualizar los KPIs en pantalla.
 */
function actualizarKpisTransacciones(data) {
    let total = data.length;
    let finalizados = 0;
    let entradas = 0;
    let salidas = 0;
    let verificados = 0;
    
    // Contadores por tipo
    let pedidos = 0;
    let traslados = 0;
    let compras = 0;

    data.forEach(item => {
        // 1. Conteo por Tipo de Transacción
        if (item.TIPO_TRANSACCION === "Pedidos") pedidos++;
        if (item.TIPO_TRANSACCION === "Traslados") traslados++;
        if (item.TIPO_TRANSACCION === "Compras") compras++;

        // 2. Entrada vs Salida
        if (item["ENTRADA / SALIDA"] === "Entrada") entradas++;
        if (item["ENTRADA / SALIDA"] === "Salida") salidas++;

        // 3. Verificados (Si tiene nombre de verificador o cantidad verificada > 0)
        if (item["VERIFICADO POR"] !== null || parseFloat(item["CANT VERIFICADA"]) > 0) {
            verificados++;
        }

        // 4. Lógica de Finalizados (Basado en tu regla de CANT CONTADA/VERIFICADA)
        const cantContada = parseFloat(item["CANT CONTADA"]) || 0;
        const cantVerificada = parseFloat(item["CANT VERIFICADA"]) || 0;
        if (cantContada > 0 || cantVerificada > 0) {
            finalizados++;
        }
    });

    const porcFinalizado = ((finalizados / total) * 100).toFixed(1);
    const porcVerificado = ((verificados / total) * 100).toFixed(1);

    // Actualizar los IDs en el HTML
    document.getElementById('kpi_pedidos').innerText = pedidos;
    document.getElementById('kpi_traslados').innerText = traslados;
    document.getElementById('kpi_compras').innerText = compras;
    document.getElementById('kpi_eficiencia').innerText = porcFinalizado + "%";
    
    // Extras para los nuevos cards
    if(document.getElementById('kpi_entradas')) document.getElementById('kpi_entradas').innerText = entradas;
    if(document.getElementById('kpi_salidas')) document.getElementById('kpi_salidas').innerText = salidas;
    if(document.getElementById('kpi_verificados')) document.getElementById('kpi_verificados').innerText = porcVerificado + "%";
}
/**
 * 1. Gráfico de "Productividad por Hora" (Line Chart)
 */
function renderizarGraficoProductividad(data) {
    const horas = [...Array(24).keys()].map(h => `${h.toString().padStart(2, '0')}:00`);
    let conteoPorHora = new Array(24).fill(0);

    data.forEach(item => {
        if (item["FECHA HORA APLICACION"]) {
            const hora = new Date(item["FECHA HORA APLICACION"]).getHours();
            conteoPorHora[hora]++;
        }
    });

    new Chart(document.getElementById('chartProductividadReal'), {
        type: 'line',
        data: {
            labels: horas.slice(7, 19), // Mostramos de 7am a 6pm
            datasets: [{
                label: 'Transacciones Procesadas',
                data: conteoPorHora.slice(7, 19),
                borderColor: '#00ced1',
                backgroundColor: 'rgba(0, 206, 209, 0.1)',
                fill: true,
                tension: 0.4
            }]
        },
        options: { responsive: true, maintainAspectRatio: false }
    });
}
/*
*2. Gráfico de "Top 5 Artículos más Movidos" (Horizontal Bar)
*/
function renderizarTopArticulos(data) {
    const conteoArticulos = {};
    
    data.forEach(item => {
        const art = item.ARTICULO;
        const cant = Math.abs(parseFloat(item["CANT APLICADA"])) || 0;
        conteoArticulos[art] = (conteoArticulos[art] || 0) + cant;
    });

    // Ordenar y sacar los 5 mejores
    const sorted = Object.entries(conteoArticulos)
        .sort((a, b) => b[1] - a[1])
        .slice(0, 5);

    new Chart(document.getElementById('chartTopArticulos'), {
        type: 'bar',
        data: {
            labels: sorted.map(x => x[0]),
            datasets: [{
                label: 'Cantidad Aplicada',
                data: sorted.map(x => x[1]),
                backgroundColor: '#f4a261'
            }]
        },
        options: { indexAxis: 'y', responsive: true }
    });
}
/**
 * 3. Gráfico de "Precisión de Conteo" (Doughnut)
 */
let myChartPrecision = null;
function renderizarGraficoPrecision(data) {
    const canvas = document.getElementById('chartPrecision');
    if (!canvas) return;

    let discrepancia = 0;
    let exacto = 0;

    data.forEach(item => {
        const aplicada = item["CANT APLICADA"] ? Math.abs(parseFloat(item["CANT APLICADA"])) : 0;
        const contada = item["CANT CONTADA"] ? Math.abs(parseFloat(item["CANT CONTADA"])) : 0;
        if (contada > 0) {
            (aplicada === contada) ? exacto++ : discrepancia++;
        }
    });

    const total = exacto + discrepancia;
    const porcentaje = total > 0 ? (exacto / total) : 0;

    if (myChartPrecision) { myChartPrecision.destroy(); }

    myChartPrecision = new Chart(canvas, {
        type: 'doughnut',
        data: {
            labels: ['Exacto', 'Discrepancia'],
            datasets: [{
                data: [exacto, discrepancia],
                backgroundColor: ['#2a9d8f', '#e76f51'],
                borderWidth: 0,
                cutout: '80%',
                circumference: 180,
                rotation: 270
            }]
        },
        options: {
            responsive: true,
            maintainAspectRatio: false,
            layout: { padding: { bottom: 30 } },
            plugins: {
                legend: { display: false },
                tooltip: { enabled: false }
            }
        },
        plugins: [{
            id: 'gaugeNeedle',
            afterDatasetsDraw: (chart) => {
                const { ctx, data, chartArea: { width, height } } = chart;
                ctx.save();
                
                // 1. Encontrar el centro del gráfico
                const xCenter = width / 2;
                const yCenter = chart._metasets[0].data[0].y; // Punto central del arco
                const outerRadius = chart._metasets[0].data[0].outerRadius;

                // 2. Calcular ángulo de la aguja (de 0 a 180 grados, convertido a radianes)
                // Math.PI es 180 grados. 0% es Math.PI (izq), 100% es 0 (der).
                // const angle = Math.PI + (porcentaje * Math.PI);
                 const angle = Math.PI-porcentaje;

                // 3. Dibujar la Aguja
                ctx.translate(xCenter, yCenter);
                //  ctx.translate(xCenter, 20);
                ctx.rotate(angle);
                // ctx.rotate(100);
                ctx.beginPath();
                ctx.moveTo(3, -3); // Grosor de la base de la aguja
                ctx.lineTo(-outerRadius * 1.0, 0); // Largo de la aguja
                ctx.lineTo(3, 3); // Grosor de la base
                ctx.fillStyle = '#f1390a';
                ctx.fill();

                // 4. Dibujar el punto central (el tornillo de la aguja)
                ctx.beginPath();
                ctx.arc(0, 0, 6, 0, Math.PI * 2);
                ctx.fill();
                ctx.restore();

                // 5. Dibujar Texto del Porcentaje
                ctx.save();
                ctx.font = 'bold 1.8em Orbitron';
                ctx.fillStyle = (porcentaje * 100) < 90 ? '#ece3e3' : '#e5e9ec';
                ctx.textAlign = 'center';
                ctx.fillText((porcentaje * 100).toFixed(1) + '%', xCenter, yCenter);
                ctx.restore();
            }
        }]
    });
}
function renderizarTablaTotales(data) {
    let totales = {
        contadas: 0,
        verificadas: 0,
        entradas: 0,
        salidas: 0
    };

    data.forEach(item => {
        const cantAplicada = Math.abs(parseFloat(item["CANT APLICADA"])) || 0;
        const cantContada = Math.abs(parseFloat(item["CANT CONTADA"])) || 0;
        const cantVerificada = Math.abs(parseFloat(item["CANT VERIFICADA"])) || 0;

        // Sumatoria de Auditoría
        totales.contadas += cantContada;
        totales.verificadas += cantVerificada;

        // Sumatoria por Flujo
        if (item["ENTRADA / SALIDA"] === "Entrada") {
            totales.entradas += cantAplicada;
        } else {
            totales.salidas += cantAplicada;
        }
    });

    const tabla = document.getElementById('tablaTotalesOperativos');
    
    // Formateador de números (Panamá usa formato US: 1,234.50)
    const f = new Intl.NumberFormat('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });

    const filas = [
        { nombre: "Total Cantidades Contadas", valor: totales.contadas, icon: "inventory", color: "cyan-text" },
        { nombre: "Total Cantidad Verificadas", valor: totales.verificadas, icon: "verified", color: "green-text" },
        { nombre: "Total de Entradas (Abastecimiento)", valor: totales.entradas, icon: "file_download", color: "blue-text" },
        { nombre: "Total de Salidas (Despachos)", valor: totales.salidas, icon: "file_upload", color: "orange-text" }
    ];

    tabla.innerHTML = filas.map(fila => `
        <tr>
            <td class="left-align"><i class="material-icons left ${fila.color}">${fila.icon}</i> ${fila.nombre}</td>
            <td><b class="black-text">${f.format(fila.valor)}</b></td>
            <td><span class="badge ${fila.valor > 0 ? 'blue' : 'grey'} white-text">Actualizado</span></td>
        </tr>
    `).join('');
}

